ALTER TABLE tenants ADD COLUMN canonical_host TEXT NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN origin TEXT NOT NULL DEFAULT '';
ALTER TABLE auth_transactions ADD COLUMN origin TEXT NOT NULL DEFAULT '';
ALTER TABLE auth_codes ADD COLUMN origin TEXT NOT NULL DEFAULT '';
ALTER TABLE pushed_auth_requests ADD COLUMN origin TEXT NOT NULL DEFAULT '';
ALTER TABLE device_codes ADD COLUMN origin TEXT NOT NULL DEFAULT '';
ALTER TABLE refresh_tokens ADD COLUMN origin TEXT NOT NULL DEFAULT '';
ALTER TABLE password_reset_tickets ADD COLUMN origin TEXT NOT NULL DEFAULT '';
ALTER TABLE email_verification_tickets ADD COLUMN origin TEXT NOT NULL DEFAULT '';
CREATE TABLE custom_domains (tenant_id TEXT NOT NULL, id TEXT NOT NULL, domain TEXT NOT NULL, revision BIGINT NOT NULL, next_attempt_at BIGINT NULL, payload TEXT NOT NULL, PRIMARY KEY (tenant_id,id), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE host_bindings (host TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, domain_id TEXT NOT NULL, generation BIGINT NOT NULL, kind VARCHAR(16) NOT NULL, active BOOLEAN NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE custom_domain_defaults (tenant_id TEXT PRIMARY KEY, domain_id TEXT NOT NULL, FOREIGN KEY (tenant_id,domain_id) REFERENCES custom_domains(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE custom_domain_attempts (tenant_id TEXT NOT NULL, domain_id TEXT NOT NULL, attempted_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,domain_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE custom_tenant_attempts (tenant_id TEXT NOT NULL, position INTEGER NOT NULL, attempted_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,position), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE tls_assets (asset_key TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, domain_id TEXT NOT NULL, revision BIGINT NOT NULL, expires_at BIGINT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE tls_leases (resource_key TEXT PRIMARY KEY, owner TEXT NOT NULL, fence BIGINT NOT NULL, lease_until BIGINT NOT NULL);
CREATE INDEX custom_domains_due ON custom_domains (next_attempt_at);
CREATE INDEX host_bindings_tenant ON host_bindings (tenant_id);
CREATE INDEX tls_assets_owner ON tls_assets (tenant_id,domain_id);
CREATE INDEX tls_assets_expiry ON tls_assets (expires_at);
